def wolfeAtomicTouchedCells (M : JLMS.AtomicDualModel 𝕜 K)
    (μ : WeakDual 𝕜 (JLMS.CZero 𝕜 K)) (U : I → Set K) : Set I :=
  {i | ∃ x ∈ U i, M.representation (WeakDual.toStrongDual μ) x ≠ 0}

